class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int hold = -prices[0];
        int sold = 0;
        int rest = 0;
        for (int i = 1; i < (int)prices.size(); i++) {
            int newHold = max(hold, rest - prices[i]);
            int newSold = hold + prices[i];
            int newRest = max(rest, sold);
            hold = newHold;
            sold = newSold;
            rest = newRest;
        }
        return max(sold, rest);
    }
};
